PRAGMA foreign_keys=ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, UNIQUE(providerId,accountId));
CREATE INDEX account_user ON account(userId);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER, updatedAt INTEGER);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE categories (id TEXT PRIMARY KEY,name TEXT NOT NULL,position INTEGER NOT NULL);
CREATE TABLE quizzes (id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,category_id TEXT NOT NULL REFERENCES categories(id),title TEXT NOT NULL,outline TEXT NOT NULL,current_version INTEGER,position INTEGER NOT NULL);
CREATE INDEX quizzes_category ON quizzes(category_id);
CREATE TABLE quiz_versions (quiz_id TEXT NOT NULL REFERENCES quizzes(id),version INTEGER NOT NULL,body TEXT NOT NULL,published_at TEXT NOT NULL,PRIMARY KEY(quiz_id,version));
CREATE TABLE progress (user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE,quiz_id TEXT NOT NULL,version INTEGER NOT NULL,cursor INTEGER NOT NULL DEFAULT 0,completed INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,quiz_id,version),FOREIGN KEY(quiz_id,version) REFERENCES quiz_versions(quiz_id,version));
CREATE TABLE research_participants (id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES user(id) ON DELETE CASCADE,profile TEXT NOT NULL,consent_version TEXT NOT NULL,consented_at TEXT NOT NULL);
CREATE TABLE research_answers (participant_id TEXT NOT NULL REFERENCES research_participants(id) ON DELETE CASCADE,quiz_id TEXT NOT NULL,version INTEGER NOT NULL,question_id TEXT NOT NULL,choice_id TEXT NOT NULL,profile TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(participant_id,quiz_id,version,question_id),FOREIGN KEY(quiz_id,version) REFERENCES quiz_versions(quiz_id,version));
CREATE INDEX answers_question ON research_answers(quiz_id,version,question_id);
CREATE TABLE perceptions (participant_id TEXT NOT NULL REFERENCES research_participants(id) ON DELETE CASCADE,quiz_id TEXT NOT NULL,version INTEGER NOT NULL,phase TEXT NOT NULL CHECK(phase IN ('before','after')),value INTEGER CHECK(value BETWEEN 1 AND 5),profile TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(participant_id,quiz_id,version,phase),FOREIGN KEY(quiz_id,version) REFERENCES quiz_versions(quiz_id,version));
CREATE TABLE admin_audit (id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,action TEXT NOT NULL,quiz_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE quiz_drafts (quiz_id TEXT PRIMARY KEY REFERENCES quizzes(id),body TEXT NOT NULL,updated_at TEXT NOT NULL);
